475: function updateState(dt) {
476:   const stats = getVehicleStats();
477:   const terrain = sampleTerrain(player.x, player.y);
478:   const maxSpeed = stats.maxSpeed;
479:   const angularForce = state.lowRange ? 1.1 : 0.9;
480: 
481:   if (keyState.KeyW) {
482:     player.speed += stats.acceleration * dt * terrain.traction;
483:   }
484:   if (keyState.KeyS) {
485:     player.speed -= stats.braking * dt * 0.78;
486:   }
487:   if (!keyState.KeyW && !keyState.KeyS) {
488:     player.speed *= 0.98 * terrain.drag;
489:   }
490: 
491:   if (keyState.KeyA) {
492:     player.dir -= dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
493:   }
494:   if (keyState.KeyD) {
495:     player.dir += dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
496:   }
497: 
498:   player.speed = clamp(player.speed, -16, maxSpeed);
499: 
500:   const turnSlip = Math.abs((keyState.KeyA || keyState.KeyD) ? player.speed * 0.12 : 0);
501:   const surfaceBreak = terrain.surface * (state.build.boggers ? 0.85 : 1);
502:   player.slip = clamp((Math.abs(player.speed) / (stats.maxSpeed + 1)) * 100 * (1 / terrain.traction) * surfaceBreak + turnSlip, 0, 100);
503: 
504:   if (Math.abs(player.speed) < 4 && (keyState.KeyA || keyState.KeyD)) {
505:     player.slip *= 0.7;
506:   }
507: 
508:   const sideways = Math.sin(player.dir) * player.speed;
509:   const forward = Math.cos(player.dir) * player.speed;
510:   player.x += forward * dt * 16;
511:   player.y += sideways * dt * 16;
512: 
513:   player.x = clamp(player.x, 30, world.width - 30);
514:   player.y = clamp(player.y, 30, world.height - 30);
515: 
516:   if (terrain.type === 'water') {
517:     const riverPush = 0.15 + (player.speed * 0.02);
518:     player.x += Math.cos(Math.PI * 0.5) * riverPush * dt * 80;
519:     player.y += Math.sin(Math.PI * 0.75) * riverPush * dt * 48;
520:     player.waterDepth = clamp(Math.abs(player.speed) * 0.022, 0, 2.4);
521:   } else {
522:     player.waterDepth = 0;
523:   }
524: 
525:   if (terrain.type === 'peat') {
526:     player.speed *= 0.994;
527:     if (Math.abs(player.speed) < 3) player.speed *= 0.98;
528:   }
529: 
530:   if (terrain.type === 'mud') {
531:     player.speed *= 0.996;
532:   }
533: 
534:   if (terrain.type === 'snow') {
535:     player.speed *= 0.999;
536:   }
537: 
538:   if (terrain.type === 'rock') {
539:     player.speed *= 0.999;
540:     player.chassis = clamp(player.chassis - 0.01, 0, 100);
541:   }
542: 
543:   if (state.build.sealedIgnition) {
544:     player.engine = clamp(player.engine + 0.02, 0, 100);
545:   }
546: 
547:   if (terrain.type === 'water' && !state.build.snorkel) {
548:     player.engine = clamp(player.engine - 0.06, 0, 100);
549:   }
550: 
551:   if (state.winchActive) {
552:     const target = missionStops[Math.min(state.missionIndex, missionStops.length - 1)];
553:     const d = distanceToPoint(player, target);
554:     if (d > 0) {
555:       const pull = clamp((state.build.winch ? 1.4 : 1) * dt * 44, 0, 44);
556:       const dir = Math.atan2(target.y - player.y, target.x - player.x);
557:       player.x += Math.cos(dir) * pull * 0.7;
558:       player.y += Math.sin(dir) * pull * 0.7;
559:       player.speed = clamp(player.speed * 0.98 + 0.8, -2, 18);
560:       if (d < 85) {
561:         player.speed *= 0.8;
562:       }
563:     }
564:   }
565: 
566:   if (player.speed < 0) {
567:     player.selectedGear = 'R';
568:     player.gearMode = 'LOW';
569:   } else if (Math.abs(player.speed) > 0.5) {
570:     player.selectedGear = state.lowRange ? '2' : '4';
