152: function getRoadDistance(x, y) {
153:   let best = Infinity;
154:   for (let i = 0; i < world.route.length - 1; i += 1) {
155:     const a = world.route[i];
156:     const b = world.route[i + 1];
157:     const dx = b.x - a.x;
158:     const dy = b.y - a.y;
159:     const t = clamp(((x - a.x) * dx + (y - a.y) * dy) / (dx * dx + dy * dy || 1), 0, 1);
160:     const px = a.x + dx * t;
161:     const py = a.y + dy * t;
162:     const dist = Math.hypot(x - px, y - py);
163:     if (dist < best) best = dist;
164:   }
165:   return best;
166: }
