475: function updateState(dt) {
476:   const stats = getVehicleStats();
477:   const terrain = sampleTerrain(player.x, player.y);
478:   const maxSpeed = stats.maxSpeed;
479:   const angularForce = state.lowRange ? 1.1 : 0.9;
480:   const softGround = terrain.type === 'mud' || terrain.type === 'peat' || terrain.type === 'snow';
481:   const pressureBonus = softGround && state.tirePressure <= 18 ? 0.12 : 0;
482:   const effectiveTraction = clamp(terrain.traction * stats.traction * stats.diffMul * (state.awd ? 1 : 0.72) * (1 + pressureBonus), 0.12, 1.4);
483: 
484:   if (keyState.KeyW) {
485:     player.speed += stats.acceleration * dt * effectiveTraction;
486:   }
487:   if (keyState.KeyS) {
488:     player.speed -= stats.braking * dt * 0.78;
489:   }
490:   if (!keyState.KeyW && !keyState.KeyS) {
491:     player.speed *= 0.98 * terrain.drag;
492:   }
493: 
494:   if (keyState.KeyA) {
495:     player.dir -= dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
496:   }
497:   if (keyState.KeyD) {
498:     player.dir += dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
499:   }
500: 
501:   player.speed = clamp(player.speed, -16, maxSpeed);
502: 
503:   const turnSlip = Math.abs((keyState.KeyA || keyState.KeyD) ? player.speed * 0.12 : 0);
504:   const surfaceBreak = terrain.surface * (state.build.boggers ? 0.85 : 1);
505:   player.slip = clamp((Math.abs(player.speed) / (stats.maxSpeed + 1)) * 100 * (1 / effectiveTraction) * surfaceBreak + turnSlip, 0, 100);
506: 
507:   if (Math.abs(player.speed) < 4 && (keyState.KeyA || keyState.KeyD)) {
508:     player.slip *= 0.7;
509:   }
510: 
511:   const sideways = Math.sin(player.dir) * player.speed;
512:   const forward = Math.cos(player.dir) * player.speed;
513:   player.x += forward * dt * 16;
514:   player.y += sideways * dt * 16;
515: 
516:   player.x = clamp(player.x, 30, world.width - 30);
517:   player.y = clamp(player.y, 30, world.height - 30);
518: 
519:   if (terrain.type === 'water') {
