531:   }
532: 
533:   if (terrain.type === 'mud') {
534:     player.speed *= 0.996;
535:   }
536: 
537:   if (terrain.type === 'snow') {
538:     player.speed *= 0.999;
539:   }
540: 
541:   if (terrain.type === 'rock') {
542:     player.speed *= 0.999;
543:     player.chassis = clamp(player.chassis - 0.01, 0, 100);
544:   }
545: 
546:   if (state.build.sealedIgnition && terrain.type === 'water') {
