585: 
586:   player.rpm = 830 + Math.abs(player.speed) * 28 + (state.lowRange ? 150 : 0);
587:   player.fuel = clamp(player.fuel - Math.abs(player.speed) * 0.004 * dt * 60, 0, 100);
588:   player.tyres = clamp(player.tyres - (player.slip / 220) * dt * 60, 0, 100);
589:   player.engine = clamp(player.engine - (player.slip / 210) * dt * 60 + (state.build.radiatorRelocation ? 0.03 : 0), 0, 100);
