495: function updateState(dt) {
496:   const stats = getVehicleStats();
497:   const terrain = sampleTerrain(player.x, player.y);
498:   const maxSpeed = stats.maxSpeed;
499:   const angularForce = state.lowRange ? 1.1 : 0.9;
500:   const softGround = terrain.type === 'mud' || terrain.type === 'peat' || terrain.type === 'snow';
501:   const pressureBonus = softGround && state.tirePressure <= 18 ? 0.12 : 0;
502:   const effectiveTraction = clamp(terrain.traction * stats.traction * stats.diffMul * (state.awd ? 1 : 0.72) * (1 + pressureBonus), 0.12, 1.4);
503: 
504:   if (keyState.KeyW) {
505:     player.speed += stats.acceleration * dt * effectiveTraction;
506:   }
507:   if (keyState.KeyS) {
508:     player.speed -= stats.braking * dt * 0.78;
509:   }
510:   if (!keyState.KeyW && !keyState.KeyS) {
511:     player.speed *= 0.98 * terrain.drag;
512:   }
513: 
514:   if (keyState.KeyA) {
515:     player.dir -= dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
516:   }
517:   if (keyState.KeyD) {
518:     player.dir += dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
519:   }
520: 
521:   player.speed = clamp(player.speed, -16, maxSpeed);
522: 
523:   const turnSlip = Math.abs((keyState.KeyA || keyState.KeyD) ? player.speed * 0.12 : 0);
524:   const surfaceBreak = terrain.surface * (state.build.boggers ? 0.85 : 1);
525:   player.slip = clamp((Math.abs(player.speed) / (stats.maxSpeed + 1)) * 100 * (1 / effectiveTraction) * surfaceBreak + turnSlip, 0, 100);
526: 
527:   if (Math.abs(player.speed) < 4 && (keyState.KeyA || keyState.KeyD)) {
528:     player.slip *= 0.7;
529:   }
530: 
531:   const sideways = Math.sin(player.dir) * player.speed;
532:   const forward = Math.cos(player.dir) * player.speed;
533:   player.x += forward * dt * 16;
534:   player.y += sideways * dt * 16;
535: 
536:   player.x = clamp(player.x, 30, world.width - 30);
537:   player.y = clamp(player.y, 30, world.height - 30);
538: 
539:   if (terrain.type === 'water') {
540:     const riverPush = 0.15 + (player.speed * 0.02);
541:     player.x += Math.cos(Math.PI * 0.5) * riverPush * dt * 80;
542:     player.y += Math.sin(Math.PI * 0.75) * riverPush * dt * 48;
543:     player.waterDepth = clamp(Math.abs(player.speed) * 0.022, 0, 2.4);
544:   } else {
545:     player.waterDepth = 0;
546:   }
547: 
548:   if (terrain.type === 'peat') {
549:     player.speed *= 0.994;
550:     if (Math.abs(player.speed) < 3) player.speed *= 0.98;
551:   }
552: 
553:   if (terrain.type === 'mud') {
554:     player.speed *= 0.996;
555:   }
556: 
557:   if (terrain.type === 'snow') {
558:     player.speed *= 0.999;
559:   }
560: 
561:   if (terrain.type === 'rock') {
562:     player.speed *= 0.999;
563:     player.chassis = clamp(player.chassis - 0.01, 0, 100);
564:   }
565: 
566:   if (state.build.sealedIgnition && terrain.type === 'water') {
567:     player.engine = clamp(player.engine + 0.015, 0, 100);
568:   }
569: 
570:   if (terrain.type === 'water') {
571:     const waterSpeed = Math.abs(player.speed);
572:     const fordLimit = stats.fordDepth;
573:     const crossedLimit = waterSpeed > 12 && !state.build.snorkel;
574:     const crossingDamage = player.waterDepth > fordLimit ? (state.build.sealedIgnition ? 0.025 : 0.065) : 0.008;
575:     player.engine = clamp(player.engine - crossingDamage * dt * 60, 0, 100);
576:     player.chassis = clamp(player.chassis - (player.waterDepth > fordLimit + 0.2 ? 0.012 : 0) * dt * 60, 0, 100);
577:     player.waterDepth = Math.min(1.25, 0.35 + waterSpeed * 0.008);
578:   }
579: 
580:   if (state.winchActive && state.winchAnchor) {
581:     const dx = state.winchAnchor.x - player.x;
582:     const dy = state.winchAnchor.y - player.y;
583:     const distance = Math.hypot(dx, dy);
584:     if (distance > 10) {
585:       const pull = Math.min(distance, stats.recoveryPower * 9 * dt);
586:       player.x += (dx / distance) * pull;
587:       player.y += (dy / distance) * pull;
588:       player.speed *= 0.92;
