621:   if (terrain.type === 'road' && Math.abs(player.speed) < 10) {
622:     player.slip = clamp(player.slip * 0.97 - truckBias, 0, 100);
623:   }
624: 
625:   checkMission();
626:   updateVehicleUI();
627: }
