665: function updateState(dt) {
666:   const stats = getVehicleStats();
667:   let terrain = sampleTerrain(player.x, player.y);
668:   const maxSpeed = stats.maxSpeed;
669:   const angularForce = state.lowRange ? 1.1 : 0.9;
670:   const softGround = terrain.type === 'mud' || terrain.type === 'peat' || terrain.type === 'snow';
671:   const pressureBonus = softGround && state.tirePressure <= 18 ? 0.12 : 0;
672:   const effectiveTraction = clamp(terrain.traction * stats.traction * stats.diffMul * (state.awd ? 1 : 0.72) * (1 + pressureBonus), 0.12, 1.4);
673: 
674:   if (keyState.KeyW) {
675:     player.speed += stats.acceleration * dt * effectiveTraction;
676:   }
677:   if (keyState.KeyS) {
678:     player.speed -= stats.braking * dt * 0.78;
679:   }
680:   if (!keyState.KeyW && !keyState.KeyS) {
681:     player.speed *= 0.98 * terrain.drag;
682:   }
683: 
684:   if (keyState.KeyA) {
685:     player.dir -= dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
686:   }
687:   if (keyState.KeyD) {
688:     player.dir += dt * (0.8 + Math.abs(player.speed) * 0.02) * angularForce;
689:   }
690: 
691:   player.speed = clamp(player.speed, -16, maxSpeed);
692: 
693:   const turnSlip = Math.abs((keyState.KeyA || keyState.KeyD) ? player.speed * 0.12 : 0);
694:   const surfaceBreak = terrain.surface * (state.build.boggers ? 0.85 : 1);
695:   player.slip = clamp((Math.abs(player.speed) / (stats.maxSpeed + 1)) * 100 * (1 / effectiveTraction) * surfaceBreak + turnSlip, 0, 100);
696: 
697:   if (Math.abs(player.speed) < 4 && (keyState.KeyA || keyState.KeyD)) {
698:     player.slip *= 0.7;
699:   }
700: 
701:   const sideways = Math.sin(player.dir) * player.speed;
702:   const forward = Math.cos(player.dir) * player.speed;
703:   player.x += forward * dt * 16;
704:   player.y += sideways * dt * 16;
705: 
706:   player.x = clamp(player.x, 30, world.width - 30);
707:   player.y = clamp(player.y, 30, world.height - 30);
708:   terrain = sampleTerrain(player.x, player.y);
709: 
710:   if (terrain.type === 'water') {
711:     const riverPush = 0.15 + (player.speed * 0.02);
712:     player.x += Math.cos(Math.PI * 0.5) * riverPush * dt * 80;
713:     player.y += Math.sin(Math.PI * 0.75) * riverPush * dt * 48;
714:     player.waterDepth = clamp(1.05 * (1 - getRiverDistance(player.x, player.y) / 50), 0.05, 1.05);
715:   } else {
716:     player.waterDepth = 0;
717:   }
718: 
719:   if (terrain.type === 'peat') {
720:     player.speed *= 0.994;
721:     if (Math.abs(player.speed) < 3) player.speed *= 0.98;
722:   }
723: 
724:   if (terrain.type === 'mud') {
725:     player.speed *= 0.996;
726:   }
727: 
728:   if (terrain.type === 'snow') {
729:     player.speed *= 0.999;
730:   }
731: 
732:   if (terrain.type === 'rock') {
733:     player.speed *= 0.999;
734:     player.chassis = clamp(player.chassis - 0.01, 0, 100);
735:   }
736: 
737:   if (terrain.type === 'water') {
738:     const waterSpeed = Math.abs(player.speed);
739:     const overFordLimit = player.waterDepth > stats.fordDepth;
740:     const fastUnsnorkelledCrossing = waterSpeed > 12 && !state.build.snorkel;
741:     const crossingDamage = overFordLimit
742:       ? (state.build.sealedIgnition ? 0.025 : 0.065) * (fastUnsnorkelledCrossing ? 1.35 : 1)
743:       : 0.008;
744:     player.engine = clamp(player.engine - crossingDamage * dt * 60, 0, 100);
745:     if (player.waterDepth > stats.fordDepth + 0.15) {
746:       player.chassis = clamp(player.chassis - 0.012 * dt * 60, 0, 100);
747:     }
748:   }
749: 
750:   if (state.winchActive && state.winchAnchor) {
751:     const hook = getWinchHookPosition();
752:     const dx = state.winchAnchor.x - hook.x;
753:     const dy = state.winchAnchor.y - hook.y;
754:     const distance = Math.hypot(dx, dy);
755:     if (distance > 12) {
756:       const pull = Math.min(distance - 12, stats.recoveryPower * 9 * dt);
757:       player.x += (dx / distance) * pull;
